<script setup lang="ts">
import {Modal as AModal,Descriptions as ADescriptions,DescriptionsItem as ADescriptionsItem,InputNumber as AInputNumber,Tag as ATag} from 'ant-design-vue'
import StatePanel from './StatePanel.vue'
import {ref,watch,computed} from 'vue'
import {correlationFields,type CorrelationRule} from '../correlation'
import {formatTime} from '../types'
const props=defineProps<{record:CorrelationRule|null;pending?:boolean;error?:string;revision:number;maximum:number}>()
const emit=defineEmits<{close:[];read:[revision:number]}>()
const choice=ref<number|null>(props.revision),validChoice=computed(()=>choice.value!==null&&Number.isSafeInteger(choice.value)&&choice.value>=1&&choice.value<=props.maximum)
watch(()=>props.revision,value=>{choice.value=value})
function read(){if(!props.pending&&validChoice.value&&choice.value!==null)emit('read',choice.value)}
function choose(value:number|string|null){choice.value=value===null||value===''?null:Number(value)}
</script>
<template><a-modal :open="true" title="关联规则修订" :width="760" :body-style="{maxHeight:'calc(100vh - 240px)',overflowY:'auto'}" @cancel="emit('close')"><div class="correlation-revision"><label for="correlation-revision">读取修订</label><a-input-number id="correlation-revision" :value="choice??''" @update:value="choose" :min="1" :max="maximum" :precision="0" :disabled="pending"/><a-button :loading="pending" :disabled="pending||!validChoice" @click="read">读取</a-button></div><StatePanel :loading="pending" :error="error" @retry="emit('read',revision)"><a-descriptions v-if="record" bordered :column="1" size="small"><a-descriptions-item label="规则">{{record.name}} / <span class="technical">{{record.id}}</span></a-descriptions-item><a-descriptions-item label="修订 / 状态">{{record.revision}} / {{record.active?'允许回测':'停用'}}</a-descriptions-item><a-descriptions-item label="数据来源">已有告警快照</a-descriptions-item><a-descriptions-item label="分组">接入探针 + 注册代次 + {{correlationFields[record.definition.group_by]}}</a-descriptions-item><a-descriptions-item label="计量">{{record.definition.metric==='count'?'唯一告警条数':'不同'+correlationFields[record.definition.distinct_field]+'数量'}}</a-descriptions-item><a-descriptions-item label="窗口 / 阈值">{{record.definition.window_seconds}} 秒 / {{record.definition.threshold}}</a-descriptions-item><a-descriptions-item label="过滤条件"><pre class="correlation-filter">{{record.definition.filter||'范围内全部告警'}}</pre></a-descriptions-item><a-descriptions-item label="维护说明">{{record.description||'未填写'}}</a-descriptions-item><a-descriptions-item label="保存时间 / 操作者">{{formatTime(record.created_at)}} / {{record.created_by}}</a-descriptions-item><a-descriptions-item label="定义 SHA-256"><span class="technical correlation-digest">{{record.definition_sha256}}</span></a-descriptions-item><a-descriptions-item label="历史保留截止">{{formatTime(record.expires_at)}}；当前配置受引用保护。</a-descriptions-item></a-descriptions></StatePanel><p class="page-description section-gap">历史修订仅供核对；窗口回测必须使用当前允许回测的固定修订，不发布实时关联或设备处置。</p><template #footer><a-button @click="emit('close')">关闭</a-button></template></a-modal></template>
<style scoped>:deep(.ant-descriptions-item-content){overflow-wrap:anywhere}.correlation-revision{display:flex;align-items:center;gap:8px;margin-bottom:12px}.correlation-filter{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}.correlation-digest{overflow-wrap:anywhere}</style>
